from __future__ import annotations
import math
from dataclasses import dataclass

K_B: float = 1.380649e-23

@dataclass(frozen=True)
class Resources:
    n: int
    states: int
    erased_bits: float
    minimum_height: int
    work_joules: float

def calculate(n: int, temperature: float = 300.0) -> Resources:
    if n < 0 or temperature < 0:
        raise ValueError("n and temperature must be nonnegative")
    states = math.factorial(n)
    log_factorial = math.lgamma(n + 1)
    bits = log_factorial / math.log(2.0)
    height = 0 if states == 1 else (states - 1).bit_length()
    return Resources(n, states, bits, height, K_B * temperature * log_factorial)

if __name__ == "__main__":
    for n in (0, 3, 5, 10, 20):
        print(calculate(n))

from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class PaddingResult:
    original_height: int
    padded_height: int
    original_leaves: int
    padded_leaves: int

def pad_tree_statistics(height: int, leaves: int, levels: int) -> PaddingResult:
    if min(height, levels) < 0 or leaves < 1:
        raise ValueError("invalid tree statistics")
    return PaddingResult(height, height + levels, leaves, leaves * (2 ** levels))

if __name__ == "__main__":
    result = pad_tree_statistics(height=22, leaves=3_628_800, levels=10)
    print(result)
    print("The visible map, erased bits, and Landauer scale are unchanged.")

